WITH analysis_source AS (
  SELECT convert_from(decode('{{$json.request_analysis_json_b64}}','base64'),'UTF8')::jsonb AS report
)
INSERT INTO content_outputs (job_id, output_type, title, structured_data, qa_status)
VALUES (NULLIF('{{$json.job_id}}','')::uuid, 'request_analysis', 'Request analysis', (SELECT report FROM analysis_source), 'pending');
UPDATE content_jobs SET status='waiting_for_analysis_approval', updated_at=now() WHERE id=NULLIF('{{$json.job_id}}','')::uuid;
INSERT INTO content_events (job_id,event_type,message,metadata) VALUES (NULLIF('{{$json.job_id}}','')::uuid,'approval_gate','Request analysis approval gate reached',jsonb_build_object('approval_stage','analysis'));
SELECT NULLIF('{{$json.job_id}}','') AS job_id, 'waiting_for_analysis_approval' AS status;

